# Frequent first-request specializations from real off/xy exterior workers.
# Captured with Julia 1.12.6 and the pinned Metal stack. Compile types only;
# never construct fake GPU buffers or launch an engine kernel during a build.
# Keep the dependency internals under Metal's own module bindings.
function metal_channel_task_wrapper_type()
    # Channel's task captures these fields, but its generated name changes
    # between Julia patch releases. Resolve the type rather than its number.
    wrappers = Set{UnionAll}()
    for name in names(Base; all=true)
        isdefined(Base, name) || continue
        value = getfield(Base, name)
        value isa UnionAll || continue
        T = Base.unwrap_unionall(value)
        if T isa DataType && T <: Function && fieldnames(T) == (:func, :chnl)
            push!(wrappers, value)
        end
    end
    return only(wrappers)
end

# Resolve driver closures by captured fields, never compiler-generated numbers.
# Fail on ambiguity rather than silently precompiling an unrelated closure.
function compiled_driver_closure_type(fields)
    matches = Any[]
    for name in names(@__MODULE__; all=true)
        isdefined(@__MODULE__, name) || continue
        value = getfield(@__MODULE__, name)
        value isa UnionAll || value isa DataType || continue
        T = Base.unwrap_unionall(value)
        T <: Function && fieldnames(T) == fields && push!(matches, value)
    end
    return only(matches)
end

