    # packed regular/singular/field signatures, with exact storage modes.
    for (f, args) in metal_host_signatures()
        f === Core.kwcall && length(args) >= 2 && args[2] <: Metal.HostKernel || continue
        kernel = args[2]
        function_type = kernel.parameters[1]
        host_args = args[3:end]
        push!(signatures, Tuple{typeof(Metal.encode_arguments!), Metal.MTL.MTLComputeCommandEncoder,
            kernel, Metal.KernelState, function_type, host_args...})
        push!(signatures, Tuple{typeof(Base.map), typeof(Metal.mtlconvert), Tuple{host_args...}})
        push!(signatures, Tuple{typeof(Base.append!), Vector{Any}, Tuple{function_type,Tuple{host_args...}}})
    end
    return unique(signatures)
end

function precompile_metal_runtime_signatures()
    successes = 0
    failures = 0
    for (index, signature) in enumerate(metal_runtime_signatures())
        try
            precompile(signature) || error("No matching runtime method")
            successes += 1
        catch exception
            failures += 1
            @warn "BEAT Metal runtime precompile failed" index signature exception=(exception, catch_backtrace())
        end
    end
    @info "BEAT Metal runtime workload complete" compiled_signatures=successes failures
end
